(()=>{
 const status=document.querySelector('#status'),list=document.querySelector('#list');let context;
 function wav(data){const n=data.ch.length,len=data.ch[0].length,buf=new ArrayBuffer(44+len*n*2),v=new DataView(buf);let o=0;const str=s=>{for(const c of s)v.setUint8(o++,c.charCodeAt(0))},u16=x=>{v.setUint16(o,x,true);o+=2},u32=x=>{v.setUint32(o,x,true);o+=4};str('RIFF');u32(36+len*n*2);str('WAVEfmt ');u32(16);u16(1);u16(n);u32(data.sr);u32(data.sr*n*2);u16(n*2);u16(16);str('data');u32(len*n*2);for(let i=0;i<len;i++)for(let c=0;c<n;c++){let x=Math.max(-1,Math.min(1,data.ch[c][i]||0));v.setInt16(o,x<0?x*32768:x*32767,true);o+=2}return new Blob([buf],{type:'audio/wav'})}
 for(const [id,info] of Object.entries(alongAudio.catalog)){const row=document.createElement('div');row.className='item';const label=document.createElement('strong');label.textContent=id;const play=document.createElement('button');play.textContent='试听';const save=document.createElement('button');save.textContent='下载 WAV';const detail=document.createElement('small');detail.textContent=`${info.sr} Hz · ${info.variants} 个变体${info.loop?' · 循环':''}${info.ir?' · 混响脉冲响应':''}　变体：`;const variant=document.createElement('input');variant.type='number';variant.min='0';variant.max=info.variants-1;variant.value='0';detail.append(variant);row.append(label,play,save,detail);list.append(row);
 const generate=()=>{let n=Number(variant.value);if(!Number.isInteger(n)||n<0||n>=info.variants)throw Error('变体编号必须在 0 到 '+(info.variants-1)+' 之间');return alongAudio.synthesize(id,n)};
 play.onclick=async()=>{try{context ||= new AudioContext();await context.resume();status.textContent='正在生成 '+id+'…';await new Promise(r=>setTimeout(r,20));const data=generate(),buffer=context.createBuffer(data.ch.length,data.ch[0].length,data.sr);data.ch.forEach((c,i)=>buffer.copyToChannel(c,i));const node=context.createBufferSource();node.buffer=buffer;node.connect(context.destination);node.start();status.textContent='正在试听 '+id}catch(e){status.textContent='音效生成失败：'+e.message;console.error(e)}};
 save.onclick=async()=>{try{status.textContent='正在生成 '+id+'…';await new Promise(r=>setTimeout(r,20));const url=URL.createObjectURL(wav(generate())),a=document.createElement('a');a.href=url;a.download=id+'-'+variant.value+'.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='已生成 '+a.download}catch(e){status.textContent='音效导出失败：'+e.message;console.error(e)}};
 }
})();
